local ADDON, ns = ...
local L = ns.L
-- Guild verification (Verify.lua, /oly verify): a guild master verifies his guild once with a
-- verifier (the King, a High Councillor or the addon's author), who approves it in The Watch.
L.VERIFY_TITLE = "Guild verification"
-- Who a guild master contacts to verify, as the notice says it. A text, never a name in the code.
L.VERIFY_CONTACT = "a member of the High Council, or the Olympus website team"
-- A character the Whisper button writes to first ("": none, the verifiers online instead). A
-- release may name the verifier who takes these whispers by default.
L.VERIFY_WHISPER_TO = ""
L.VERIFY_NOTICE_MASTER_GRACE = "GM verification pending: your guild <%s> is not verified by Olympus yet.\n\nComplete your guild verification within %s. Contact a verifier using the steps below.\n\nHow to verify:\n1. Whisper %s. The Whisper button below writes it for you; Ask the High Council asks those online.\n2. Give them your guild, your character and this code: %s\n3. Once they approve, your guild is verified on every Olympus client. Nothing else to do."
L.VERIFY_NOTICE_MASTER_LATE = "GM verification overdue: your guild <%s> is not sanctioned by Olympus, its guild master has not verified it.\n\nContact a verifier to complete your guild verification. The High Council has your guild on its follow-up list.\n\nHow to verify:\n1. Whisper %s. The Whisper button below writes it for you; Ask the High Council asks those online.\n2. Give them your guild, your character and this code: %s\n3. Once they approve, your guild is verified on every Olympus client. Nothing else to do."
L.VERIFY_NOTICE_LAPSED = "<%s> was verified with %s as its guild master. A verification belongs to the guild and its guild master: the new guild master verifies again, on the guild's same deadline."
L.VERIFY_NOTICE_MEMBER = "Your guild <%s> is not sanctioned by Olympus yet: its guild master (%s) has not verified it.\n\nOlympus guilds are verified by their guild masters, so the army knows who is part of it. Ask your guild master to verify: they type /oly verify (or install Olympus first, if they don't have it). If you want to be part of the Olympus community, you can also find another Olympus guild: the Census lists them."
L.VERIFY_NO_GATE = "Nothing is taken from the members and nobody is removed: this is a notice."
L.VERIFY_NOTICE_HOLD = "Until you are verified, your guild master powers in Olympus are on hold: you stand as an officer, and your guild's public card, your Legates and correspondents, your guild decrees and your guild bank grant wait. They come back as soon as a verifier approves you."
